import ebUrls from '../../../../../request/urls/employeeBenefit'

const actions = {
  ADD_EMPLOYEE_REQUEST: 'ADD_EMPLOYEE_REQUEST',
  ADD_EMPLOYEE: 'ADD_EMPLOYEE',
  addEmployee: payload => ({
    type: actions.ADD_EMPLOYEE_REQUEST,
    payload: {
      ...payload,
      method: 'post',
      url: ebUrls.addEmployee
    }
  })
}

export default actions
