/* eslint-disable react-hooks/exhaustive-deps */
import React, { useEffect } from 'react'
import {
  Button,
  Typography,
  Row,
  Col,
  Select,
  Input,
  Form,
  Icon,
  Alert,
  Spin,
  Divider,
  DatePicker,
  Modal,
  Badge
} from 'antd'
import LayoutContentWrapper from '../../../../../../components/utility/layoutWrapper'
import LayoutContent from '../../../../../../components/utility/layoutContent'
import { RowWithMargin } from '../../../CommonComponents'
import { ColTextAlignCenter, ColTextAlignRight } from '../../../CommonComponents/index.style'
import { useAddEmployee } from '../../../state/AddEmployee/hooks/useAddEmployee'
import { getDependentsError, getEmployeeError } from './utility'
import { emailRegExp, phoneRegExp } from './constants'
import { ModalContentWrapper, SuccessIcon } from './index.style'
import { trimFirstZeroFromPhone } from '../../../../../../helpers/utility'
import { useErrorContextValue, useLoaderContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import { useResetState } from '../../../state/hooks'
import { addEmployeeValidations } from './validations'

const { Title, Text } = Typography
const { Option } = Select

let id = 0

const AddParticipant = ({ match, ...props }) => {
  const { history } = props
  const { form } = props
  const { getFieldDecorator, getFieldValue } = form
  const { resetState } = useResetState()
  const { resetError } = useResetError()
  const { addEmployeeData, addEmployee } = useAddEmployee()
  const [{ ADD_EMPLOYEE_ERROR, addEmployeeStatus, addEmployeeErrorData }] = useErrorContextValue()
  const [{ ADD_EMPLOYEE_LOADER }] = useLoaderContextValue()

  const goBack = () => {
    history.goBack()
  }

  getFieldDecorator('keys', { initialValue: ['employee'] })

  const add = () => {
    // can use data-binding to get
    const keys = form.getFieldValue('keys')
    const nextKeys = keys.concat(id++)
    // can use data-binding to set
    // important! notify form to detect changes
    form.setFieldsValue({
      keys: nextKeys
    })
  }

  const remove = k => {
    // can use data-binding to get
    const keys = form.getFieldValue('keys')
    // can use data-binding to set
    form.setFieldsValue({
      keys: keys.filter(key => key !== k)
    })
  }

  const handleOnOk = () => {
    history.push({
      pathname: `/employee-benefits/company-list/${match.params.id}/participants-list`,
      state: { activeTab: 2 }
    })
  }

  const handleSubmit = (e) => {
    e.preventDefault()
    form.validateFields((err, values) => {
      const valuesToBeSent = {
        employee: values.employee
      }
      valuesToBeSent.employee.company_id = match.params.id
      valuesToBeSent.employee.dob = values.employee.dob?.format('YYYY-MM-DD')
      valuesToBeSent.employee.effective_join_date = values.employee.effective_join_date?.format('YYYY-MM-DD')
      valuesToBeSent.employee.phone = values.employee.phone ? `62-${trimFirstZeroFromPhone(values.employee.phone)}` : ''
      valuesToBeSent.employee_dependents = []

      for (const key of values.keys) {
        if (key === 'employee') {
          if (!(Object.values(values.employee.policy_data).reduce((prevValue, value) => prevValue || !!value))) {
            delete valuesToBeSent.employee.policy_data
          }
          continue
        } else {
          const dependent = { ...values[key] }
          dependent.dob = dependent.dob.format('YYYY-MM-DD')
          dependent.effective_join_date = dependent.effective_join_date?.format('YYYY-MM-DD')
          if (!(Object.values(dependent.policy_data).reduce((prevValue, value) => prevValue || !!value))) {
            delete dependent.policy_data
          }
          valuesToBeSent.employee_dependents.push(dependent)
        }
      }

      if (!err) {
        resetError(['ADD_EMPLOYEE_ERROR'])
        addEmployee(valuesToBeSent)
      }
    })
  }

  useEffect(() => {
    if (addEmployeeData && addEmployeeStatus === 'success') {
      const { data } = addEmployeeData
      if (data) {
        form.resetFields()
        const { employee_dependents_failure: failedDependents, employee_dependents_success: successfulDependents } = data
        const title = failedDependents.length ? 'Participant added successfully, with some failed dependents' : 'Participant added successfully'
        const content = (
          <ModalContentWrapper>
            {
              !!successfulDependents.length && !!failedDependents.length && (
                <div>
                  <Icon type='check-square' className='success' /> Successful Dependents
                  <div className='ml-20'>
                    {successfulDependents.map((dependent, index) => (
                      <Badge key={index} status='success' text={dependent.name} />
                    ))}
                  </div>
                </div>
              )
            }
            {
              !!failedDependents.length && (
                <div>
                  <Icon type='close-square' className='error' /> Failed Dependents
                  <div className='ml-20'>
                    {failedDependents.map((dependent, index) => (
                      <Badge key={index} status='error' text={dependent.name} />
                    ))}
                  </div>
                </div>
              )
            }
          </ModalContentWrapper>
        )
        Modal.confirm({
          title,
          okText: 'Go to participants list',
          cancelText: 'Add other participant',
          onOk: handleOnOk,
          icon: !failedDependents.length ? <SuccessIcon type='check-circle' /> : <Icon type='check-circle' />,
          content
        })
      }
      resetError(['ADD_EMPLOYEE_ERROR'])
      resetState(['addEmployeeData', 'addEmployeeStatus'])
    }
  }, [addEmployeeData, addEmployeeStatus])

  useEffect(() => {
    if (ADD_EMPLOYEE_ERROR) {
      if (addEmployeeErrorData) {
        const errors = addEmployeeErrorData.error
        if (errors) {
          const values = form.getFieldsValue()
          getDependentsError(errors, values)
          form.setFields({
            employee: getEmployeeError(errors, values),
            ...getDependentsError(errors, values)
          })
        }
      }
      // resetError(['ADD_EMPLOYEE_ERROR'])
      // resetEbState(['addEmployeeData', 'addEmployeeStatus'])
    }
  }, [ADD_EMPLOYEE_ERROR])

  return (
    <>
      <LayoutContentWrapper>
        <Button type='default' onClick={goBack}><Icon type='caret-left' />Back</Button>
        <LayoutContent>
          <Spin spinning={!!ADD_EMPLOYEE_LOADER}>
            {ADD_EMPLOYEE_ERROR && (!addEmployeeErrorData) && <Alert type='error' message={addEmployeeStatus} banner />}
            <Form onSubmit={handleSubmit}>
              <Row>
                <ColTextAlignCenter>
                  <Title level={4}>Add Participant</Title>
                </ColTextAlignCenter>
              </Row>
              <RowWithMargin gutter={8}>
                {
                  getFieldValue('keys').map((key, index) => {
                    return (
                      <React.Fragment key={index}>
                        <RowWithMargin>
                          <Col span={12}>
                            <Text strong>
                              {index === 0 ? 'Employee Data' : `Dependent ${index}  Data`}
                            </Text>
                          </Col>
                          <ColTextAlignRight span={12}>
                            {
                            index !== 0
                              ? (
                                <Button
                                  type='danger'
                                  onClick={() => remove(key)}
                                >
                                  Remove Dependent <Icon type='delete' />
                                </Button>
                                )
                              : null
                            }
                          </ColTextAlignRight>
                        </RowWithMargin>
                        <Col span={12}>
                          <Form.Item
                            hasFeedback
                            label='Name'
                          >
                            {
                              getFieldDecorator(`${key}.name`,
                                {
                                  initialValue: '',
                                  validateTrigger: 'onBlur',
                                  rules: [
                                    {
                                      required: true,
                                      initialValue: '',
                                      message: 'Name is required'
                                    },
                                    {
                                      min: 2,
                                      message: 'Name should be atleast 2 character'
                                    },
                                    {
                                      max: 128,
                                      message: 'Name should not exceed 128 character'
                                    }
                                  ]
                                }
                              )(
                                <Input />
                              )
                            }
                          </Form.Item>
                        </Col>
                        <Col span={12}>
                          <Form.Item
                            required
                            hasFeedback
                            label='Date of Birth'
                          >
                            {
                            getFieldDecorator(`${key}.dob`,
                              {
                                rules: [{
                                  required: true,
                                  message: 'Date of birth is required'
                                }]
                              }
                            )(
                              <DatePicker
                                format='YYYY-MM-DD'
                                disabledDate={date => date.isAfter(new Date(), 'day')}
                              />
                            )
                          }
                          </Form.Item>
                        </Col>
                        <Col span={12}>
                          <Form.Item
                            required
                            hasFeedback
                            label='Effective Join Date'
                          >
                            {
                            getFieldDecorator(`${key}.effective_join_date`,
                              {
                                rules: [{
                                  required: true,
                                  message: 'Effective join date is required'
                                }]
                              }
                            )(
                              <DatePicker
                                format='YYYY-MM-DD'
                              />
                            )
                          }
                          </Form.Item>
                        </Col>
                        {
                          index === 0 && (
                            <Col span={12}>
                              <Form.Item
                                hasFeedback
                                label='Phone'
                              >
                                {
                                getFieldDecorator(`${key}.phone`, {
                                  validateTrigger: 'onBlur',
                                  rules: [
                                    {
                                      required: false,
                                      pattern: phoneRegExp,
                                      message: 'Please enter valid phone number'
                                    }
                                  ]
                                }
                                )(
                                  <Input
                                    type='number'
                                    addonBefore='+62'
                                  />
                                )
                              }
                              </Form.Item>
                            </Col>

                          )
                        }
                        {
                        index === 0
                          ? (
                            <Col span={12}>
                              <Form.Item
                                hasFeedback
                                label='Department'
                              // {...formLayout}
                              >
                                {
                                  getFieldDecorator(`${key}.department`,
                                    {
                                      initialValue: '',
                                      validateTrigger: 'onBlur',
                                      rules: [
                                        {
                                          initialValue: ''
                                        },
                                        {
                                          min: 2,
                                          message: 'Department should be atleast 2 character'
                                        },
                                        {
                                          max: 128,
                                          message: 'Department should not exceed 128 character'
                                        }
                                      ]
                                    }
                                  )(
                                    <Input />
                                  )
                                }
                              </Form.Item>
                            </Col>
                            )
                          : null

                      }
                        {
                        index > 0
                          ? (
                            <Col span={12}>
                              <Form.Item
                                required
                                hasFeedback
                                label='Relation with employee'
                              // {...formLayout}
                              >
                                {
                                  getFieldDecorator(`${key}.relation_with_employee`,
                                    {
                                      initialValue: '',
                                      rules: [{
                                        initialValue: '',
                                        required: true,
                                        message: 'Relation with employee is required'
                                      }]
                                    }
                                  )(
                                    <Select>
                                      <Option value='Anak'>Anak</Option>
                                      <Option value='Pasangan'>Pasangan</Option>
                                    </Select>
                                  )
                                }
                              </Form.Item>
                            </Col>
                            )
                          : null
                      }
                        <Col span={12}>
                          <Form.Item
                            required
                            hasFeedback
                            label='Gender'
                          >
                            {
                            getFieldDecorator(`${key}.gender`,
                              {
                                initialValue: '',
                                rules: [{
                                  initialValue: '',
                                  required: true,
                                  message: 'Gender is required'
                                }]
                              }
                            )(
                              <Select>
                                <Option
                                  value='Perempuan'
                                >
                                  Perempuan
                                </Option>
                                <Option value='Laki-laki'>
                                  Laki-laki
                                </Option>
                              </Select>
                            )
                          }
                          </Form.Item>
                        </Col>
                        <Col span={12}>
                          <Form.Item
                            hasFeedback
                            label='Plan'
                          >
                            {
                            getFieldDecorator(`${key}.plan`,
                              {
                                initialValue: '',
                                validateTrigger: 'onBlur',
                                rules: [
                                  {
                                    initialValue: ''

                                  },
                                  {
                                    max: 10,
                                    message: 'Plan should not exceed 10 character'
                                  }
                                ]
                              }
                            )(
                              <Input />
                            )
                          }
                          </Form.Item>
                        </Col>
                        {
                          index === 0 && (
                            <Col span={12}>
                              <Form.Item
                                hasFeedback
                                label='Email'
                              >
                                {
                                getFieldDecorator(`${key}.email`,
                                  {
                                    initialValue: '',
                                    validateTrigger: 'onBlur',
                                    rules: [
                                      {
                                        initialValue: ''
                                      },
                                      {
                                        required: false,
                                        pattern: emailRegExp,
                                        message: 'Enter a valid email address'
                                      }
                                    ]
                                  }
                                )(
                                  <Input />
                                )
                              }
                              </Form.Item>
                            </Col>
                          )
                        }
                        <Col span={12}>
                          <Form.Item
                            hasFeedback
                            label='E-Card Company Name'
                          >
                            {
                              getFieldDecorator(`${key}.policy_data.company_name`, {
                                validateTrigger: 'onBlur',
                                rules: addEmployeeValidations.company_name(form, key)
                              })(
                                <Input maxLength={55} />
                              )
                            }
                          </Form.Item>
                        </Col>
                        <Col span={12}>
                          <Form.Item
                            hasFeedback
                            label='E-Card Policy Number'
                          >
                            {
                              getFieldDecorator(`${key}.policy_data.policy_number`, {
                                validateTrigger: 'onBlur',
                                rules: addEmployeeValidations.policy_number(form, key)
                              })(
                                <Input maxLength={27} />
                              )
                            }
                          </Form.Item>
                        </Col>
                        <Col span={12}>
                          <Form.Item
                            hasFeedback
                            label='E-Card Number'
                          >
                            {
                              getFieldDecorator(`${key}.policy_data.card_number`, {
                                validateTrigger: 'onBlur',
                                rules: addEmployeeValidations.card_number(form, key)
                              })(
                                <Input maxLength={27} />
                              )
                            }
                          </Form.Item>
                        </Col>
                        <Divider />
                      </React.Fragment>
                    )
                  })
                }

                <ColTextAlignRight span={24}>
                  <Button
                    type='primary'
                    onClick={add}
                  >
                    Add Dependent <Icon type='user-add' />
                  </Button>
                </ColTextAlignRight>
              </RowWithMargin>
              <RowWithMargin>
                <ColTextAlignCenter span={24}>
                  <Button type='primary' htmlType='submit'>Submit</Button>
                </ColTextAlignCenter>
              </RowWithMargin>
            </Form>
            {/* <Modal
              visible={modalVisible}
              onCancel={() => setModalVisible(false)}
              cancelText='Add another employee'
              okText='Go to participant list'
              title='Employee added successfully'
              onOk={handleOnOk}
            >
              Please choose between below options
            </Modal> */}
          </Spin>
        </LayoutContent>
      </LayoutContentWrapper>
    </>
  )
}

const WrappedformComponent = Form.create({ name: 'add-participant-form' })(AddParticipant)

export default WrappedformComponent
