export function getEmployeeError (errors, values) {
  const errorObject = {}
  for (const key in values.employee) {
    if (key === 'policy_data') {
      errorObject.policy_data = {
        card_number: {
          value: values.employee[key]?.card_number,
          errors: Array.isArray(errors.employee[key]?.card_number) ? errors.employee[key].card_number.map(err => new Error(err)) : null
        },
        policy_number: {
          value: values.employee[key]?.policy_number,
          errors: Array.isArray(errors.employee[key]?.policy_number) ? errors.employee[key].policy_number.map(err => new Error(err)) : null
        },
        company_name: {
          value: values.employee[key]?.company_name,
          errors: Array.isArray(errors.employee[key]?.company_name) ? errors.employee[key].company_name.map(err => new Error(err)) : null
        }
      }
      continue
    }
    errorObject[key] = {
      value: values.employee[key],
      errors: Array.isArray(errors.employee[key]) ? errors.employee[key].map(err => new Error(err)) : null
    }
  }
  return errorObject
}

function mapDependentsFieldLevelError (errors, values) {
  const errorObject = {}
  for (const key in values) {
    errorObject[key] = {
      value: values[key],
      errors: Array.isArray(errors[key]) ? errors[key].map(err => new Error(err)) : null
    }
  }
  return errorObject
}

export function getDependentsError (errors, values) {
  const errorObject = {}
  const valuesClone = { ...values }
  const keys = [...valuesClone.keys]
  keys.shift()
  if (Array.isArray(errors.employee_dependents)) {
    for (let i = 0; i < errors.employee_dependents.length; i++) {
      errorObject[keys[i]] = mapDependentsFieldLevelError(
        errors.employee_dependents[i],
        values[keys[i]]
      )
    }
  }
  return errorObject
}
