import { useServiceRequest } from '@pasarpolis/common-react-hooks'
import { useEBContextValue } from '../../../context/index'
import actions from '../actions'

export const useAddEmployee = () => {
  const [{ addEmployeeData, addEmployeeStatus }, dispatch] = useEBContextValue()
  const [callApi] = useServiceRequest(dispatch)

  const addEmployee = async (payload = {}) => {
    await callApi(actions.addEmployee({ body: payload }))
  }
  return { addEmployeeData, addEmployeeStatus, addEmployee }
}
