const isOneOfCardFieldsFilled = (form, key) => {
  const participantData = form.getFieldsValue()[key]
  const { policy_number: policy, card_number: cardNo, company_name: company } = participantData?.policy_data || {}
  return policy || cardNo || company
}

export const addEmployeeValidations = {
  policy_number: (form, key) => [
    {
      required: isOneOfCardFieldsFilled(form, key),
      message: 'Policy Number is Required'
    },
    {
      max: 27,
      message: 'Policy Number Cannot be more than 27 characters'
    }
  ],
  card_number: (form, key) => [
    {
      required: isOneOfCardFieldsFilled(form, key),
      message: 'Card Number is required'
    }
  ],
  company_name: (form, key) => [
    {
      required: isOneOfCardFieldsFilled(form, key),
      message: 'E-Card company name is required'
    }
  ]
}
